compareBodies.before:
display: none;
position: absolute;
top: calc(100% + 4px);
right: 0;
background: var(--bg-card);
border: 1px solid var(--border);
border-radius: var(--radius-sm);
box-shadow: var(--shadow);
z-index: 50;
min-width: 160px;
padding: 6px 0;

compareBodies.after:
display: none;
position: absolute;
top: calc(100% + 4px);
right: 0;
background: var(--bg-card);
border: 1px solid var(--border);
border-radius: var(--radius-sm);
box-shadow: var(--shadow);
z-index: 50;
min-width: 160px;
padding: 6px 0;

compareBodies.before:
display: flex;
align-items: center;
gap: 8px;
padding: 6px 14px;
font-size: 13px;
color: var(--text-secondary);
cursor: pointer;
white-space: nowrap;

compareBodies.after:
display: flex;
align-items: center;
gap: 8px;
padding: 6px 14px;
font-size: 13px;
color: var(--text-secondary);
cursor: pointer;
white-space: nowrap;

compareBodies.before:
background: var(--bg-card);
border-radius: var(--radius);
border: 1px solid var(--border);
padding: 20px;
margin-bottom: 20px;
display: flex;
align-items: center;
gap: 12px;
flex-wrap: wrap;

compareBodies.after:
background: var(--bg-card); border-radius: var(--radius);
border: 1px solid var(--border); padding: 20px; margin-bottom: 20px;
display: flex; align-items: center; gap: 12px; flex-wrap: wrap;

compareBodies.before:
display: inline-flex;
align-items: center;
gap: 8px;
min-width: 0;

compareBodies.after:
display: inline-flex;
align-items: center;
gap: 8px;
min-width: 0;

compareBodies.before:
padding: 8px 12px;
border-radius: 6px;
border: 1px solid var(--border);
background: var(--bg-primary);
color: var(--text-primary);
font-size: 13px;
font-family: inherit;
cursor: pointer;
min-width: 160px;

compareBodies.after:
padding: 8px 12px; border-radius: 6px; border: 1px solid var(--border);
background: var(--bg-primary); color: var(--text-primary); font-size: 13px;
font-family: inherit; cursor: pointer; min-width: 160px;

compareBodies.before:
padding: 8px 12px;
border-radius: 6px;
border: 1px solid var(--border);
background: transparent;
color: var(--text-secondary);
font-size: 16px;
cursor: pointer;
transition: all 0.15s;
font-family: inherit;

compareBodies.after:
padding: 8px 12px; border-radius: 6px; border: 1px solid var(--border);
background: transparent; color: var(--text-secondary); font-size: 16px;
cursor: pointer; transition: all 0.15s; font-family: inherit;

/* overflow: clip does not establish a scroll container, so sticky th
   descendants reference the outer (html) scroll context: the page. This
   avoids the double-scrollbar of a wrapper-bound scroll. The horizontal
   overflow fallback lives in the narrow-viewport media query below. */
overflow-x: clip;
overflow-y: visible;
min-width: 0;

compareBodies.before:
background: var(--bg-secondary);
padding: 10px 14px;
text-align: left;
font-weight: 600;
font-size: 11px;
text-transform: uppercase;
letter-spacing: 0.5px;
color: var(--text-muted);
border-bottom: 1px solid var(--border);
white-space: nowrap;
position: sticky;
top: var(--app-sticky-top, 65px);
z-index: 2;

compareBodies.after:
background: var(--bg-secondary); padding: 10px 14px; text-align: left;
font-weight: 600; font-size: 11px; text-transform: uppercase;
letter-spacing: 0.5px; color: var(--text-muted);
border-bottom: 1px solid var(--border); white-space: nowrap;
/* Stick to the page scroll context, offset by the sticky page header
   so it does not slide behind it. */
position: sticky; top: var(--app-sticky-top, 65px); z-index: 2;

compareBodies.before:
padding: 10px 14px;
border-bottom: 1px solid var(--border);
font-variant-numeric: tabular-nums;

background: var(--bg-secondary);
font-weight: 600;
font-size: 12px;
text-transform: uppercase;
letter-spacing: 0.5px;
color: var(--text-muted);
padding: 8px 14px;

compareBodies.after:
background: var(--bg-secondary); font-weight: 600; font-size: 12px;
text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted);
padding: 8px 14px;

compareBodies.before:
display: flex;
align-items: baseline;
flex-wrap: wrap;
gap: 3px 5px;

compareBodies.after:
display: flex;
align-items: baseline;
flex-wrap: wrap;
gap: 3px 5px;

compareBodies.before:
color: var(--text-muted);
font-size: 10px;
font-weight: 600;
letter-spacing: 0.02em;
text-transform: uppercase;

compareBodies.after:
color: var(--text-muted);
font-size: 10px;
font-weight: 600;
letter-spacing: 0.02em;
text-transform: uppercase;

compareBodies.before:
border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--border));
border-radius: 999px;
color: var(--accent);
font-size: 9px;
font-weight: 700;
letter-spacing: 0.04em;
padding: 0 4px;
text-transform: uppercase;

compareBodies.after:
border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--border));
border-radius: 999px;
color: var(--accent);
font-size: 9px;
font-weight: 700;
letter-spacing: 0.04em;
padding: 0 4px;
text-transform: uppercase;

compareBodies.before:
display: grid;
grid-template-columns: 1fr auto;
align-items: end;
gap: 12px;

compareBodies.after:
display: grid;
grid-template-columns: 1fr auto;
align-items: end;
gap: 12px;
